INSERT INTO `search_dataset` (`sid`, `langcode`, `type`, `data`, `reindex`) VALUES
(1, 'ru', 'help_search', ' просмотр объявлений drupal что такое объявления drupal  лента объявлений о проекте drupal и программах ассоциации drupal цель этого канала предоставить канал для общения непосредственно с владельцами сайтов drupal этот контент должен быть в высшей степени релевантен интересам владельцев сайтов служить стратегическим целям проекта и или способствовать устойчивости проекта и ассоциации drupal модуль получает свое содержимое из канала json созданного здесь  политика управления контентом описана здесь  как я могу увидеть объявления на своем сайте  если модуль toolbar включён то в административном меню есть прямая ссылка если же он выключен то содержимое всегда можно найти на странице объявления  кто может видеть объявления  пользователи с разрешением смотреть официальные оповещения касающиеся drupal могут просматривать объявления drupal дополнительные ресурсы обзор модуля announcement объявления  ', 1791366811),
(1, 'ru', 'node_search', ' way8 главная way8 главная way8 cтудия  медиа музыка студия разработки цифровая медиасеть и музыкальный лейбл admin ср 7 окт 2026 1307  ', 0),
(2, 'ru', 'help_search', ' управление блоками что такое блоки  блоки это части контента отображаемого в области или регионе вебстраницы вашего сайта блоки размещаются и настраиваются специально для каждой темы что такое пользовательские блоки  пользовательские блоки это такие блоки содержимое которых вы можете редактировать вы можете создать один или более типов блоков и добавить к ним поля пользовательские блоки могут быть размещены как и другие блоки предоставляемые модулями что такое описание блока  описание блока это идентификационное имя для блока которое отображается в административном интерфейсе не отображается на сайте что такое заголовок блока  заголовок блока это заголовок который необязательно отображается посетителям сайта когда блок размещается в регионе обзор управления блоками модуль block позволяет размещать блоки в регионах которые заданы в ваших темах и задавать их настройки модуль block content позволяет управлять типами блоков и пользовательскими блоками информацию по решению вопросов смотрите в списке страниц справки ниже дополнительные ресурсы блоки руководство пользователя drupal  ', 1791366811),
(2, 'ru', 'node_search', ' 403 403 admin ср 7 окт 2026 1307 доступ запрещен  ', 0),
(3, 'ru', 'help_search', ' настройка ранее размещённого блока цель настройте параметры блока который ранее был помещен в регион темы шаги в разделе управление меню администратора перейдите в структура   схема блоков  нажмите на название темы которая содержит блок при желании нажмите показать регионы  чтобы увидеть регионы темы если вы хотите изменить только регион в котором расположен блок или порядок блоков внутри региона перетащите блоки в их нужные позиции и нажмите сохранить блоки  если вы хотите изменить дополнительные настройки найдите регион в котором в данный момент находится блок который вы хотите обновить и нажмите настроить в строке описания блока отредактируйте настройки блока доступные настройки различаются в зависимости от модуля который предоставляет блок но для всех блоков вы можете изменить  заголовок блока  заголовок блока на вашем сайте для некоторых блоков вам необходимо установить флажок переопределить заголовок  чтобы ввести заголовок показать заголовок  установите флажок если хотите чтобы заголовок отображался видимость  добавьте условия для отображения блока регион  изменить регион темы в которой отображается блок нажмите сохранить блок   ', 1791366811),
(3, 'ru', 'node_search', ' 404 404 admin ср 7 окт 2026 1308 страница не найдена  ', 0),
(4, 'ru', 'help_search', ' размещение блока цель поместите блок в регион темы шаги в административном меню управление перейдите к структура  схема блоков нажмите на название темы в которую вы хотите поместить блок при желании нажмите показать регионы  чтобы увидеть регионы темы найдите регион в котором вы хотите блок и нажмите поместить блок в этот регион появится модальное диалоговое окно найдите блок который вы хотите разместить и нажмите поместить блок  появится модальное диалоговое окно configure block  настройте блок и нажмите сохранить блок  см настройка ранее размещённого блока для подробностей конфигурации  ', 1791366811),
(4, 'ru', 'node_search', ' way8 медиа way8 медиа контент way8 медиа admin пт 9 окт 2026 242  ', 0),
(5, 'ru', 'help_search', ' создание контентблока цель создать пользовательский блок который затем может быть размещён на сайте шаги в разделе управление меню администратора перейдите в содержимое  откройте вкладку контентблоки нажмите добавить блок  если на вашем сайте создано больше одного типа блока нажмите название типа который вы хотите создать введите описание вашего блока которое будет показано администраторам и основной текст вашего блока нажмите сохранить   ', 1791366811),
(5, 'ru', 'node_search', ' way8 музыка way8 музыка контент way8 музыка admin вт 13 окт 2026 136  ', 0),
(6, 'ru', 'help_search', ' создание типа блока цель создать тип блока и его поля шаги в разделе управление меню администратора перейдите в структура   типы блоков  нажмите добавить тип блока  введите заголовок для этого типа блока отображается в административном интерфейсе при необходимости отредактируйте автоматически сгенерированное имя машины или описание нажмите сохранить  вы вернетесь на страницу типы блоков  нажмите управление полями в строке нового типа блока и добавьте нужные поля в тип блока при желании нажмите управление отображением формы или управление отображением  чтобы изменить форму редактирования или отображение поля для вашего типа блока  ', 1791366811),
(6, 'ru', 'node_search', ' way8 студия way8 студия контент way8 студия admin вт 13 окт 2026 139  ', 0),
(7, 'ru', 'help_search', ' управление точками перехода высоты ширины и разрешения экрана что такое точки перехода  точки перехода это точки в которых контент вашего сайта будет реагировать чтобы предоставить пользователю наилучший макет для использования информации точка перехода разделяет высоту или ширину видовых экранов экранов принтеров и других типов вывода мультимедиа на шаги например точка перехода ширины 40em создает два шага один для ширины до 40em и один для ширины более 40em точки перехода можно использовать для определения когда макеты должны переходить из одной формы в другую когда следует изменять размер изображений и другие изменения которые должны реагировать на изменения высоты или ширины области просмотра что такое медиа запросы  медиазапросы это способ определения точек перехода например точка перехода ширины 40em будет записана как медиазапрос minwidth 40em точки перехода это на самом деле просто медиазапросы с некоторыми дополнительными метаданными такими как имя и информация о множителе что такое коэффициент разрешения  resolution multipliers are a measure of the viewport s device resolution defined to be the ratio between the physical pixel size of the active device and the deviceindependent pixel size the breakpoint module defines multipliers of 1 15 and 2 when defining breakpoints modules and themes can define which multipliers apply to each breakpoint что такое группа точек перехода  точки перехода могут быть организованы в группы модули и темы должны использовать группы для разделения точек перехода в соответствии с их назначением например точки перехода для макетов или точки перехода для изменения размеров изображений управление точками перехода и обзор групп точек перехода модуль точка перехода  breakpoint позволяет определить точки перехода и их группы в yaml формате модули и темы могут использовать api предоставленный модулем точка перехода для определения точек перехода и их групп а также для присвоения коэффициентов разрешения точкам перехода дополнительные ресурсы работа с точками останова в drupal стандарты w3c для медиа запросов ', 1791366811),
(8, 'ru', 'help_search', ' импортируется одна запись конфигурации цель импортируйте отдельный элемент конфигурации в формате yaml например тот который был ранее экспортирован смотрите экспорт отдельного элемента конфигурации смотрите управление и развёртывание конфигураций для получения дополнительной информации о конфигурации шаги в разделе управление меню администратора перейдите в конфигурация   разработка   синхронизация конфигурации   импорт   один элемент  выберите тип конфигурации  который вы хотите импортировать на вашем компьютере или другом устройстве скопируйте конфигурацию формата yaml которую вы хотите импортировать в буфер обмена вставьте текст из буфера обмена в поле с надписью вставьте сюда свою конфигурацию  нажмите импорт   ', 1791366811),
(9, 'ru', 'help_search', ' экспортировать полную конфигурацию вашего сайта цель создайте и загрузите архив содержащий всю конфигурацию вашего сайта экспортированную в виде файлов yaml смотрите управление и развёртывание конфигураций для получения дополнительной информации о конфигурации шаги в разделе управление меню администратора перейдите в конфигурация   разработка   синхронизация конфигурации   экспортировать  нажмите экспорт и сохраните файл с архивом  ', 1791366811),
